function renderMissionCommandDeck(mission: MissionState | null, invariantIssueCount: number): void {
  if (!missionCommandDeck) return;
  const runbook = mission ? ensureMissionRunbook(mission) : null;
  const evidenceCount = mission ? ensureMissionEvidence(mission).length : 0;
  const activePaneId = mission ? normalizeMissionPaneId(mission.layout.activePaneId || 'pane-1') : 'pane-1';
  const activePaneTab = mission?.tabs.find((tab) => tab.paneId === activePaneId);
  const visiblePaneCount = mission ? missionVisiblePaneIds(mission.layout.type).length : 1;
  const readySteps = runbook ? runbook.steps.filter((step) => step.state === 'done').length : 0;
  const blockedSteps = runbook ? runbook.steps.filter((step) => step.state === 'blocked').length : 0;
  const exportState = invariantIssueCount > 0 ? 'Repair needed' : (mission ? 'Sanitized' : 'Not ready');
  const cards = [
    {
      key: 'identity',
      label: 'Mission',
      value: mission ? mission.name : 'No active mission',
      detail: mission ? mission.missionType + ' · ' + mission.mode : 'Create or restore a local workspace'
    },
    {
      key: 'active-pane',
      label: 'Active pane',
      value: missionPaneLabel(activePaneId),
      detail: activePaneTab ? activePaneTab.role + ' · ' + activePaneTab.title : 'Navigation target · no tab assigned'
    },
    {
      key: 'layout',
      label: 'Layout',
      value: mission ? missionLayoutLabel(mission.layout.type) : '1-Up',
      detail: visiblePaneCount + ' visible pane' + (visiblePaneCount === 1 ? '' : 's')
    },
    {
      key: 'runbook',
      label: 'Runbook',
      value: runbook ? runbook.steps.length + ' step' + (runbook.steps.length === 1 ? '' : 's') : '0 steps',
      detail: runbook ? readySteps + ' done · ' + blockedSteps + ' blocked · rollback visible' : 'Objective + rollback'
    },
    {
      key: 'evidence',
      label: 'Evidence',
      value: evidenceCount + ' item' + (evidenceCount === 1 ? '' : 's'),
      detail: 'Explicit pins · redaction-aware'
    },
    {
      key: 'timeline',
      label: 'Timeline',
      value: (mission?.timeline.length || 0) + ' event' + ((mission?.timeline.length || 0) === 1 ? '' : 's'),
      detail: 'Local operator trail'
    },
    {
      key: 'export',
      label: 'Export',
      value: exportState,
      detail: invariantIssueCount ? invariantIssueCount + ' state guard issue(s)' : 'Preview before sharing'
    }
  ];
  missionCommandDeck.innerHTML = cards.map((card) =>
    '<article class="mission-command-card" data-pass196-card="' + escapeHtml(card.key) + '">' +
    '<span>' + escapeHtml(card.label) + '</span>' +
    '<strong>' + escapeHtml(card.value) + '</strong>' +
    '<em>' + escapeHtml(card.detail) + '</em>' +
    '</article>'
  ).join('');
  missionCommandDeck.dataset.pass196Cards = String(cards.length);
  missionCommandDeck.dataset.pass196ActivePane = activePaneId;
  missionCommandDeck.dataset.pass196Layout = mission?.layout.type || 'single';
}

