function runFindInPage(forward = true, findNext = true): void {
  const query = findInput.value.trim();
  const tab = pass343ActiveTarget('find');
  if (!tab) return pass134Noop('find', 'No active tab or visible Mission pane is available.');
  if (!query) {
    pass343SafeStopFindInPage(tab.webview, `find:${tab.id}:empty`);
    findStatus.textContent = 'Ready';
    return;
  }
  const ok = pass343SafeFindInPage(tab.webview, query, { forward, findNext, matchCase: false }, `find:${tab.id}:${forward ? 'next' : 'previous'}`);
  findStatus.textContent = ok ? (forward ? 'Next' : 'Prev') : 'Not ready';
  document.body.dataset.pass343LastBrowserKitAction = ok ? `find:${forward ? 'next' : 'previous'}` : 'find:not-ready';
  if (!ok) setStatus('Find unavailable', `${pass134TargetLabel(tab)} is not ready for page search.`);
}

function runBrowserKitAction(action: string, detail?: DOMStringMap): void {
  switch (action) {
    case 'new-tab': closeToolMenus(undefined, false); createTabAndFocusAddress(pass351PreferredNewTabUrl()); break;
    case 'close-tab': {
      const targetTabId = pass343ActiveTarget('browser-kit')?.id || activeTabId;
      closeToolMenus(undefined, false);
      closeTab(targetTabId);
      break;
    }
    case 'pin-tab': {
      const targetTabId = pass343ActiveTarget('browser-kit')?.id || activeTabId;
      closeToolMenus(undefined, false);
      toggleBrowserTabPin(targetTabId, 'browser-kit');
      break;
    }
    case 'next-tab': closeToolMenus(undefined, false); setActiveRelativeTab(1, 'browser-kit'); break;
    case 'previous-tab': closeToolMenus(undefined, false); setActiveRelativeTab(-1, 'browser-kit'); break;
    case 'duplicate-tab': duplicateActiveTab(); break;
    case 'reopen-closed-tab': reopenClosedTab(); break;
    case 'restore-session': restoreSessionRecoverySnapshot(); break;
    case 'find': openFindBar(); break;
    case 'print': closeToolMenus(undefined, false); printTarget('print'); break;
    case 'copy-url': closeToolMenus(undefined, false); void copyActivePageUrl(); break;
    case 'open-external': closeToolMenus(undefined, false); void openActivePageExternally(); break;
    case 'bookmarks': closeToolMenus(undefined, false); openBrowserBookmarks(); break;
    case 'downloads': closeToolMenus(undefined, false); focusDownloadArtifacts(); break;
    case 'open-history-entry': {
      const entry = readBrowserHistory().find((candidate) => candidate.id === detail?.browserKitEntryId);
      if (!entry) {
        setStatus('History entry unavailable', 'The selected recent page is no longer available in this profile.');
        renderBrowserKitDailyDriver();
        break;
      }
      closeToolMenus(undefined, false);
      document.body.dataset.pass343LastBrowserKitAction = 'open-history-entry';
      navigate(entry.url, 'browser-kit');
      break;
    }
    case 'reopen-closed-entry': reopenClosedTab(detail?.browserKitClosedId); break;
    case 'zoom-in': closeToolMenus(undefined, false); setActivePageZoom('in'); break;
    case 'zoom-out': closeToolMenus(undefined, false); setActivePageZoom('out'); break;
    case 'zoom-reset': closeToolMenus(undefined, false); setActivePageZoom('reset'); break;
    default: setStatus('Browser Kit action unavailable', action || 'unknown');
  }
}

function bindBrowserKitStaticAction(buttonId: string): void {
  const button = document.getElementById(buttonId) as HTMLButtonElement | null;
  if (!button || button.dataset.pass347BrowserKitDirectBound === 'true') return;
  button.dataset.pass347BrowserKitDirectBound = 'true';
  const runBoundAction = (): void => {
    const action = button.dataset.browserKitAction;
    if (!action) return;
    runBrowserKitAction(action, button.dataset);
  };
  button.addEventListener('click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    runBoundAction();
  });
}

