function pass204DecorateOperatorCommandCenterV2Actions(actions: CommandPaletteAction[]): CommandPaletteAction[] {
  pass204AddOperatorCommandCenterV2Actions(actions);
  for (const action of actions) {
    const loweredGroup = action.group.toLowerCase();
    const loweredTitle = action.title.toLowerCase();
    if (!action.family) {
      if (loweredGroup.includes('mission view') || loweredTitle.includes('quad') || loweredTitle.includes('split') || loweredTitle.includes('pane')) action.family = 'layout';
      else if (loweredGroup.includes('mission')) action.family = 'mission';
      else if (loweredGroup.includes('profile') || loweredTitle.includes('profile')) action.family = 'profile';
      else if (loweredGroup.includes('evidence') || loweredTitle.includes('capture') || loweredTitle.includes('export')) action.family = loweredTitle.includes('export') ? 'export' : 'evidence';
      else if (loweredGroup.includes('tool') || loweredGroup.includes('devops') || loweredGroup.includes('it') || loweredTitle.includes('dns') || loweredTitle.includes('tls')) action.family = 'opstool';
      else if (loweredGroup.includes('help') || loweredGroup.includes('knowledge') || loweredTitle.includes('keyboard')) action.family = 'kb';
      else if (loweredGroup.includes('workspace')) action.family = 'workspace';
      else action.family = 'browser';
    }
    if (!action.targetScope) {
      const target = (action.target || action.detail || action.title).toLowerCase();
      action.targetScope = target.includes('all pane') ? 'all-panes'
        : target.includes('active pane') ? 'active-pane'
        : target.includes('mission') ? 'current-mission'
        : target.includes('profile') || loweredGroup.includes('profile') ? 'admin-profile'
        : target.includes('evidence') ? 'evidence-pack'
        : target.includes('export') ? 'export-packet'
        : target.includes('kb') || target.includes('guide') || loweredGroup.includes('help') ? 'knowledge-base'
        : target.includes('tool') ? 'opstools-pack'
        : target.includes('workspace') ? 'workspace'
        : 'browser-shell';
    }
    if ((action.targetScope === 'current-mission' || action.targetScope === 'active-pane' || action.targetScope === 'all-panes' || action.targetScope === 'export-packet') && !action.disabledReason) action.disabledReason = pass204ActionDisabledReason(action.targetScope);
    if (typeof action.exportSafe !== 'boolean') action.exportSafe = true;
    if (typeof action.destructive !== 'boolean') action.destructive = false;
  }
  const contracts = actions.map(pass204CommandContract);
  document.body.dataset.pass204OperatorCommandCenterV2 = PASS204_OPERATOR_COMMAND_CENTER_V2_PASS;
  document.body.dataset.pass204OperatorCommandCenterV2Contract = OPERATOR_COMMAND_CENTER_V2_CONTRACT_ID;
  document.body.dataset.pass204OperatorCommandCenterV2Summary = operatorCommandCenterV2Summary(contracts);
  document.body.dataset.pass204OperatorCommandCenterV2Families = OPERATOR_COMMAND_CENTER_V2_REQUIRED_FAMILIES.join(',');
  document.body.dataset.pass204OperatorCommandCenterV2Scopes = OPERATOR_COMMAND_CENTER_V2_REQUIRED_SCOPES.join(',');
  document.body.dataset.pass204OperatorCommandCenterV2Guardrails = JSON.stringify(OPERATOR_COMMAND_CENTER_V2_GUARDRAILS);
  return actions;
}

function commandActionSearchText(action: CommandPaletteAction): string {
  return `${action.title} ${action.detail} ${action.group} ${action.shortcut || ''} ${action.target || ''} ${action.phase || ''} ${action.family || ''} ${action.targetScope || ''} ${action.disabledReason || ''}`.toLowerCase();
}

function commandActionMeta(action: CommandPaletteAction): string {
  return [action.group, action.target ? `Target: ${action.target}` : '', action.targetScope ? `Scope: ${action.targetScope}` : '', action.disabledReason ? `Disabled: ${action.disabledReason}` : '', action.detail].filter(Boolean).join(' · ');
}

function sendActiveTabToMissionPane(paneId: string): void {
  const tab = active();
  if (!tab) {
    setStatus('No active tab to send', 'Mission Command Center');
    return;
  }
  upsertBrowserTabIntoMissionPane(tab.id, paneId, { activateLayout: true });
  setMissionActivePane(paneId);
  setStatus('Active tab sent to mission pane', paneId.replace('pane-', 'Pane '));
}

